  if(locationPending)return <div className="flow-wizard-form booking-pane booking-trip" hidden={false}><BookingSubsteps labels={['Trip','Confirm location']} step={step} onStep={setStep}><div className="booking-substep-pane" hidden={step!==0}>{facts}</div><div className="booking-substep-pane" hidden={step!==1}><DecisionBar booking={booking} onAccept={onAccept} onRejected={onRejected}/></div></BookingSubsteps></div>
  return <div className="flow-wizard-form booking-pane booking-trip" hidden={false}>{facts}{passenger&&!owner&&booking.trip?.pickup?.required&&['CONFIRMED','IN_PROGRESS'].includes(booking.status)&&<PickupCodePanel tripId={booking.trip.id}/>} {needsDecision&&<DecisionBar booking={booking} onAccept={onAccept} onRejected={onRejected}/>} {owner&&assigned&&<section className="rate-preview" aria-label={t('Driver Mode')}><h2>{t('Driver Mode · this trip')}</h2><p>{t('Your self-drive assignment is ')}{t(booking.trip.assignment_status.toLowerCase())}{t('. Trip status: ')}{codeLabel(booking.trip.status)}{t('. Complete readiness and trip operations here in your Owner workspace.')}</p></section>}</div>
